.ds {
  --ds-base-text:var(--p-ink,#2c333d);
  --ds-base-bg:var(--p-bg,#ffffff);
  --ds-base-text-md:var(--p-text-md,16px);
  --ds-base-font:var(--p-font,Pretendard, sans-serif);
  --ds-base-focus:var(--p-highlight,#6153b5);
  --ds-base-text-sm:var(--p-text-sm,13px);
  --ds-base-space-3:var(--p-space-sm,12px);
  --ds-base-muted:var(--p-muted,#59636f);
  --ds-base-border:var(--p-line,#c2cad5);
  --ds-base-radius:var(--p-radius,24px);
  --ds-base-surface:var(--p-surface,#f1f3f6);
  --ds-base-shadow:var(--p-shadow,6px 7px 16px #bbc4d166, -5px -5px 14px #ffffffed);
  --ds-base-edge:var(--p-edge,#ffffff);
  --ds-base-inset:var(--p-inset,inset 3px 3px 6px #b7c1cf55, inset -3px -3px 6px #ffffffd9);
  --ds-base-high:var(--p-high,#fafbfc);
  --ds-base-glass-shadow:var(--p-glass-shadow,0 8px 24px #38465e12);
  --ds-base-glass:var(--p-glass,#f6f8fbe8);
}
.ds {
  color:var(--ds-base-text); background:var(--ds-base-bg); font:var(--ds-base-text-md)/1.5 var(--ds-base-font);
  color-scheme:light; word-break:keep-all; overflow-wrap:anywhere; text-align:left;
}
.ds,.ds * { box-sizing:border-box; }
.ds [hidden] { display:none!important; }
.ds :is(h1,h2,h3,p,fieldset) { margin:0; }
.ds :is(button,input,select,textarea) { font:inherit; color:inherit; letter-spacing:inherit; }
.ds button { cursor:pointer; touch-action:manipulation; }
.ds button:disabled { cursor:not-allowed; }
.ds :is(button,input,select,textarea,a,[tabindex]):focus-visible { outline:3px solid var(--ds-base-focus); outline-offset:3px; }
.ds .ui-icon { display:inline-block; width:20px; height:20px; flex-shrink:0; vertical-align:middle; }
.ds .ds-demo-note { font-size:var(--ds-base-text-sm); margin-top:var(--ds-base-space-3); min-height:20px; color:var(--ds-base-muted); }
.ds .ds-surface { border:1px solid var(--ds-base-border); border-radius:var(--ds-base-radius); background:var(--ds-base-surface); }
.ds .ds-surface[data-material="raised"] { box-shadow:var(--ds-base-shadow); border-color:var(--ds-base-edge); }
.ds .ds-surface[data-material="inset"] { box-shadow:var(--ds-base-inset); background:var(--ds-base-bg); }
.ds .ds-surface[data-material="glass"] { background:var(--ds-base-high); box-shadow:var(--ds-base-glass-shadow); }
@supports (backdrop-filter:blur(16px)) { .ds .ds-surface[data-material="glass"] { background:var(--ds-base-glass); backdrop-filter:blur(16px); } }
@media(prefers-reduced-transparency:reduce) { .ds .ds-surface[data-material="glass"] { background:var(--ds-base-high); backdrop-filter:none; } }
@media(prefers-reduced-motion:reduce) { .ds * { transition:none!important; animation:none!important; } }

.ds {
  --ds-tabs-border:var(--p-line,#c2cad5);
  --ds-tabs-bg:var(--p-bg,#ffffff);
  --ds-tabs-inset:var(--p-inset,inset 3px 3px 6px #b7c1cf55, inset -3px -3px 6px #ffffffd9);
  --ds-tabs-muted:var(--p-muted,#59636f);
  --ds-tabs-surface:var(--p-surface,#f1f3f6);
  --ds-tabs-accent:var(--p-accent,#303b48);
  --ds-tabs-on-accent:var(--p-on-accent,#ffffff);
  --ds-tabs-selected-shadow:var(--p-selected-shadow,0 2px 5px #24314526);
  --ds-tabs-space-6:var(--p-space-lg,24px);
  --ds-tabs-text:var(--p-ink,#2c333d);
  --ds-tabs-high:var(--p-high,#fafbfc);
  --ds-tabs-raised:var(--p-raised,3px 4px 8px #b9c3d066, -3px -3px 8px #ffffffed);
  --ds-tabs-control-border:var(--p-control-border,#7b8592);
  --ds-tabs-control-radius:var(--p-control-radius,16px);
  --ds-tabs-soft:var(--p-soft,#d3e8de);
}
.ds .ds-tablist { display:flex; padding:5px; border:1px solid var(--ds-tabs-border); border-radius:20px; gap:4px; background:var(--ds-tabs-bg); box-shadow:var(--ds-tabs-inset); }
.ds .ds-tab { flex:1; min-width:44px; min-height:44px; padding:10px 12px; border:1px solid transparent; border-radius:14px; background:transparent; font-size:14px; color:var(--ds-tabs-muted); font-weight:550; }
.ds .ds-tab:hover { background:var(--ds-tabs-surface); }
.ds .ds-tab[aria-selected="true"] { background:var(--ds-tabs-accent); color:var(--ds-tabs-on-accent); font-weight:650; box-shadow:var(--ds-tabs-selected-shadow); }
.ds .ds-tabpanel { padding:var(--ds-tabs-space-6) 4px; font-size:14px; }
/* Looks: one tab markup, eight shapes. The chosen tab always gains a mark or a shape change, never only a color. */
.ds .ds-tabs[data-look] .ds-tab { display:inline-flex; justify-content:center; align-items:center; gap:6px; }
.ds .ds-tabs[data-look] .ds-tab .ui-icon { width:22px; height:22px; }
/* 02 underline: bare row on a hairline, a thick bar under the chosen tab */
.ds .ds-tabs[data-look="underline"] .ds-tablist { padding:0; gap:0; border:0; border-bottom:1px solid var(--ds-tabs-border); border-radius:0; background:transparent; box-shadow:none; }
.ds .ds-tabs[data-look="underline"] .ds-tab { border-radius:0; }
.ds .ds-tabs[data-look="underline"] .ds-tab[aria-selected="true"] { background:transparent; color:var(--ds-tabs-text); box-shadow:inset 0 -3px 0 var(--ds-tabs-accent); }
/* 03 segmented: gray track, the chosen segment rises as a white tile */
.ds .ds-tabs[data-look="segmented"] .ds-tablist { padding:4px; border:0; border-radius:12px; background:var(--ds-tabs-surface); box-shadow:none; }
.ds .ds-tabs[data-look="segmented"] .ds-tab { border-radius:9px; }
.ds .ds-tabs[data-look="segmented"] .ds-tab[aria-selected="true"] { background:var(--ds-tabs-high); color:var(--ds-tabs-text); border-color:var(--ds-tabs-border); box-shadow:var(--ds-tabs-raised); }
/* 04 outline: separate boxes, the chosen one gets a double-weight edge */
.ds .ds-tabs[data-look="outline"] .ds-tablist { padding:0; gap:8px; border:0; border-radius:0; background:transparent; box-shadow:none; }
.ds .ds-tabs[data-look="outline"] .ds-tab { border-color:var(--ds-tabs-control-border); border-radius:var(--ds-tabs-control-radius); background:var(--ds-tabs-high); }
.ds .ds-tabs[data-look="outline"] .ds-tab[aria-selected="true"] { background:var(--ds-tabs-high); color:var(--ds-tabs-text); border-color:var(--ds-tabs-text); box-shadow:inset 0 0 0 1px var(--ds-tabs-text); }
/* 05 float: loose pills, the chosen one filled soft and ringed */
.ds .ds-tabs[data-look="float"] .ds-tablist { padding:0; gap:8px; border:0; border-radius:0; background:transparent; box-shadow:none; }
.ds .ds-tabs[data-look="float"] .ds-tab { flex:none; padding-inline:18px; border-radius:999px; }
.ds .ds-tabs[data-look="float"] .ds-tab[aria-selected="true"] { background:var(--ds-tabs-soft); color:var(--ds-tabs-text); box-shadow:inset 0 0 0 1.5px var(--ds-tabs-text); }
/* 06 icon: picture over the name, a soft capsule behind the chosen picture */
.ds .ds-tabs[data-look="icon"] .ds-tablist { padding:0; border:0; border-bottom:1px solid var(--ds-tabs-border); border-radius:0; background:transparent; box-shadow:none; }
.ds .ds-tabs[data-look="icon"] .ds-tab { flex-direction:column; gap:4px; min-height:64px; padding:8px; border-radius:0; font-size:12px; }
.ds .ds-tabs[data-look="icon"] .ds-tab .ui-icon { box-sizing:content-box; padding:4px 16px; border-radius:999px; }
.ds .ds-tabs[data-look="icon"] .ds-tab[aria-selected="true"] { background:transparent; color:var(--ds-tabs-text); box-shadow:none; }
.ds .ds-tabs[data-look="icon"] .ds-tab[aria-selected="true"] .ui-icon { background:var(--ds-tabs-soft); stroke-width:2.2; }
/* 07 vertical: list on the left, a side bar on the chosen row; arrows go up and down */
.ds .ds-tabs[data-look="vertical"] { display:grid; grid-template-columns:minmax(96px,auto) minmax(0,1fr); align-items:start; }
.ds .ds-tabs[data-look="vertical"] .ds-tablist { flex-direction:column; padding:0 8px 0 0; gap:2px; border:0; border-right:1px solid var(--ds-tabs-border); border-radius:0; background:transparent; box-shadow:none; }
.ds .ds-tabs[data-look="vertical"] .ds-tab { justify-content:flex-start; border-radius:10px 0 0 10px; }
.ds .ds-tabs[data-look="vertical"] .ds-tab[aria-selected="true"] { background:var(--ds-tabs-surface); color:var(--ds-tabs-text); box-shadow:inset 3px 0 0 var(--ds-tabs-accent); }
.ds .ds-tabs[data-look="vertical"] .ds-tabpanel { padding:12px 16px; }
/* 08 folder: file-folder tabs, the chosen one joins the panel below */
.ds .ds-tabs[data-look="folder"] .ds-tablist { position:relative; z-index:1; padding:0 8px; gap:4px; border:0; border-radius:0; background:transparent; box-shadow:none; }
.ds .ds-tabs[data-look="folder"] .ds-tab { margin-bottom:-1px; border-color:var(--ds-tabs-border); border-radius:12px 12px 0 0; background:var(--ds-tabs-surface); }
.ds .ds-tabs[data-look="folder"] .ds-tab[aria-selected="true"] { background:var(--ds-tabs-high); color:var(--ds-tabs-text); border-bottom-color:var(--ds-tabs-high); box-shadow:none; }
.ds .ds-tabs[data-look="folder"] .ds-tabpanel { padding:16px; border:1px solid var(--ds-tabs-border); border-radius:0 0 var(--ds-tabs-control-radius) var(--ds-tabs-control-radius); background:var(--ds-tabs-high); }

(function mountParts(root) {
  root.querySelectorAll('[data-indeterminate]').forEach(input => {
    if (!input.__pattoveInitialized) { input.indeterminate = true; input.__pattoveInitialized = true; }
  });
  if (root.__pattovePartsMounted) return;
  root.__pattovePartsMounted = true;
  function selectTab(tab) {
    const tabs = tab.closest('.ds-tabs');
    tabs.querySelectorAll('[role="tab"]').forEach(item => {
      const active = item === tab;
      item.setAttribute('aria-selected', String(active)); item.tabIndex = active ? 0 : -1;
      tabs.querySelector('#' + CSS.escape(item.getAttribute('aria-controls'))).hidden = !active;
    });
    tabs.dispatchEvent(new CustomEvent('pattove:tabchange', { bubbles: true, detail: { label: tab.textContent.trim(), panel: tab.getAttribute('aria-controls') } }));
  }
  function filter(form) {
    const module = form.closest('.ds-search-module');
    const query = form.elements.query.value.trim().toLocaleLowerCase();
    const status = form.elements.status.value;
    let count = 0;
    module.querySelectorAll('[data-result]').forEach(item => {
      const match = query.split(/\s+/).every(term => item.dataset.result.toLocaleLowerCase().includes(term)) && (status === 'all' || item.dataset.resultStatus === status);
      item.hidden = !match; if (match) count++;
    });
    module.querySelector('.ds-result-count').textContent = count + '개의 컬렉션';
    module.querySelector('.ds-empty').hidden = count > 0;
    module.querySelector('.ds-demo-note').textContent = '';
  }
  root.addEventListener('submit', event => {
    if (!event.target.matches('[data-part-search]')) return;
    event.preventDefault(); filter(event.target);
  });
  root.addEventListener('change', event => {
    // The status filter is a select, or a radio chip group in the chips look.
    if (event.target.matches('[data-part-search] [name="status"]')) filter(event.target.form);
  });
  root.addEventListener('click', event => {
    const tab = event.target.closest('.ds-tab');
    if (tab) selectTab(tab);
    const button = event.target.closest('[data-part-action]');
    if (!button || button.disabled) return;
    const action = button.dataset.partAction;
    if (['open-record', 'close-record', 'save-record'].includes(action)) {
      const module = button.closest('.ds-search-module');
      const detail = module.querySelector('.ds-record-detail');
      if (action === 'save-record') {
        button.setAttribute('aria-pressed', String(button.getAttribute('aria-pressed') !== 'true'));
        module.__recordOpener.dataset.saved = button.getAttribute('aria-pressed');
        module.__recordOpener.setAttribute('aria-label', module.querySelector('.ds-record-detail h3').textContent + (button.getAttribute('aria-pressed') === 'true' ? ', 보관됨, 상세 열기' : ', 상세 열기'));
        module.querySelector('.ds-demo-note').textContent = button.getAttribute('aria-pressed') === 'true' ? '이 화면에서 컬렉션에 보관했어요.' : '보관을 해제했어요.';
        const record = module.__recordOpener.closest('[data-result]');
        module.dispatchEvent(new CustomEvent('pattove:save', { bubbles: true, detail: {
          id: record.dataset.recordId,
          title: detail.querySelector('h3').textContent,
          description: detail.querySelector('p').textContent,
          tag: record.dataset.resultStatus,
          saved: button.getAttribute('aria-pressed') === 'true'
        } }));
        return;
      }
      const open = action === 'open-record';
      if (open) {
        module.__recordOpener = button;
        const card = button.closest('.ds-card');
        detail.querySelector('h3').textContent = card.querySelector('h3').textContent;
        detail.querySelector('p').textContent = card.querySelector('.ds-card-body > p').textContent;
        detail.querySelector('[data-part-action="save-record"]').setAttribute('aria-pressed', button.dataset.saved || 'false');
      }
      module.querySelectorAll(':scope > form, :scope > .ds-result-count, :scope > .ds-results').forEach(element => { element.hidden = open; });
      detail.hidden = !open;
      module.querySelector('.ds-demo-note').textContent = '';
      if (open) detail.focus(); else module.__recordOpener?.focus();
    } else if (action === 'notify') {
      button.closest('.ds-feedback-example').querySelector('[data-part-feedback]').hidden = false;
    } else if (action === 'nav') {
      const items = [...button.closest('nav').querySelectorAll(':scope > [data-part-action="nav"]')];
      items.forEach(item => item.setAttribute('aria-pressed', String(item === button)));
      button.dispatchEvent(new CustomEvent('pattove:navigate', { bubbles: true, detail: { index: items.indexOf(button), label: button.textContent.trim() } }));
    } else if (action === 'create') {
      button.dispatchEvent(new CustomEvent('pattove:create', { bubbles: true }));
    } else if (action === 'select-card') {
      const card = button.closest('.ds-card');
      const selected = card.dataset.selected !== 'true';
      card.dataset.selected = String(selected);
      button.setAttribute('aria-pressed', String(selected));
      button.lastChild.textContent = selected ? '선택됨' : '선택하기';
      card.dispatchEvent(new CustomEvent('pattove:select', { bubbles: true, detail: { selected, title: card.querySelector('h3').textContent } }));
    } else if (action === 'reset-search') {
      const form = button.closest('.ds-search-module').querySelector('form');
      form.reset(); filter(form); form.elements.query.focus();
    } else if (action === 'press') {
      button.dispatchEvent(new CustomEvent('pattove:action', { bubbles: true, detail: { label: button.getAttribute('aria-label') || button.textContent.trim() } }));
      const region = button.closest('.ds-search-module, .part-demo, .specimen') || root;
      const output = region.querySelector('.ds-demo-note');
      if (output) {
        const card = button.closest('.ds-card');
        output.textContent = card ? card.querySelector('h3').textContent + ' 선택됨' : (button.getAttribute('aria-label') || button.textContent.trim()) + ' 버튼을 눌렀어요.';
      }
    }
  });
  root.addEventListener('keydown', event => {
    const tab = event.target.closest('.ds-tab');
    if (!tab) return;
    const list = tab.closest('[role="tablist"]');
    // A vertical tab list moves with the up and down arrows, a horizontal one with left and right.
    const [back, forward] = list.getAttribute('aria-orientation') === 'vertical' ? ['ArrowUp', 'ArrowDown'] : ['ArrowLeft', 'ArrowRight'];
    if (![back, forward, 'Home', 'End'].includes(event.key)) return;
    event.preventDefault();
    const tabs = [...list.querySelectorAll('.ds-tab')];
    const current = tabs.indexOf(tab);
    const next = event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 : (current + (event.key === forward ? 1 : -1) + tabs.length) % tabs.length;
    selectTab(tabs[next]); tabs[next].focus();
  });
})(document);

